INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (100, 3001, 0, 3001100, "2030/01/01 14:59:59", 1, -416.5, "2024/10/31 12:00:00", "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 2.1, 2, "ヤマト", 130011);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (101, 3001, 0, 3001101, "2030/01/01 14:59:59", 4, -416.5, "2024/10/31 12:00:00", "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 5.68, 2, "ヤマト", 130011);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (102, 3001, 0, 3001102, "2030/01/01 14:59:59", 1, -416.5, "2024/10/31 12:00:00", "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 0, 1, "ヤマト", 130011);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (100, 3002, 0, 3002100, "2030/01/01 14:59:59", 1, -416.5, "2024/10/31 12:00:00", "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 0, 1, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (101, 3002, 0, 3002101, "2030/01/01 14:59:59", 1, -416.5, "2024/10/31 12:00:00", "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 0, 1, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (102, 3002, 0, 3002102, "2030/01/01 14:59:59", 5, -416.5, "2024/10/31 12:00:00", "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 8.53, 2, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (103, 3002, 0, 3002103, "2030/01/01 14:59:59", 7, -416.5, "2024/10/31 12:00:00", "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 5.67, 1, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (104, 3002, 0, 3002104, "2030/01/01 14:59:59", 1, -416.5, "2024/10/31 12:00:00", "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 0, 1, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (300, 3004, 0, 3002300, "2030/01/01 14:59:59", 3, -416.5, "2024/10/31 12:00:00", "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 0, 3, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (301, 3005, 0, 3002400, "2030/01/01 14:59:59", 7, -416.5, "2024/10/31 12:00:00", "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 0, 7, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (200, 3003, 0, 3003200, "2030/01/01 14:59:59", 2, -416.5, "2024/10/31 12:00:00", "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 4.4, 1, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (201, 3003, 0, 3003201, "2030/01/01 14:59:59", 7, -416.5, "2024/10/31 12:00:00", "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 0, 7, "フブキ", 130211);
INSERT INTO `v1_d86695f6f4feffa653b12e35378875f932ed88af998d9c960d09ff4abaef055c` VALUES (202, 3003, 0, 3003202, "2030/01/01 14:59:59", 1, -416.5, "2024/10/31 12:00:00", "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 5.6, 2, "フブキ", 130211);
